 "new_string": "def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = {v for row in grid for v in row if v != background and v != 3}
    for color in markers:
        # Connect consecutive same-color markers along each row and column.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out
